#!/usr/bin/env node
// LeoBot Design: generate platform token files from design/tokens.json (single source).
//   node design/gen-tokens.mjs           write the generated files
//   node design/gen-tokens.mjs --check   exit 1 if any generated file is missing or stale
// Outputs:
//   src/mac/leophone/packages/ui/src/leo/skin/leo-tokens.css      (CSS custom properties, always loaded via styles.css)
//   src/mac/leophone/packages/ui/src/leo/skin/leoTokens.generated.ts (motion values for motion/react)
//   src/ios/Shared/LeoTokens.generated.swift                       (constants; the iOS line wires it into LeoDesignSystem)
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const repoRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const tokens = JSON.parse(readFileSync(join(repoRoot, "design/tokens.json"), "utf8"));
const HEADER = "GENERATED by design/gen-tokens.mjs from design/tokens.json — do not edit by hand.";

const bezier = (points) => `cubic-bezier(${points.join(", ")})`;
const lowerHex = (value) => (value.startsWith("#") ? value.toLowerCase() : value);
// CSS name for a color/shadow key: brandSoft -> brand-soft
const kebab = (key) => key.replace(/[A-Z]/g, (char) => `-${char.toLowerCase()}`);

function css() {
  const { motion, radius, space, color, shadow } = tokens;
  const root = [
    ...Object.entries(motion.duration).map(([step, ms]) => `  --leo-dur-${step}: ${ms}ms;`),
    `  --leo-beat: ${motion.beat / 1000}s;`,
    `  --leo-ease: ${bezier(motion.ease.out)};`,
    `  --leo-ease-settle: ${bezier(motion.ease.settle)};`,
    `  --leo-press-scale: ${motion.press.scale};`,
    `  --leo-press-dur: ${motion.press.duration}ms;`,
    ...Object.entries(space).map(([step, px]) => `  --leo-space-${step}: ${px}px;`),
    ...["field", "surface", "bubble", "composer", "pill"].map(
      (key) => `  --leo-radius-${key}: ${radius[key]}px;`,
    ),
    ...Object.entries(radius.mac).map(([key, px]) => `  --leo-radius-mac-${kebab(key)}: ${px}px;`),
  ];
  const themed = (mode) => [
    ...Object.entries(color).map(([key, value]) => `  --leo-${kebab(key)}: ${lowerHex(value[mode])};`),
    ...Object.entries(shadow).map(([key, value]) => `  --leo-shadow-${kebab(key)}: ${value[mode]};`),
  ];
  return [
    `/* ${HEADER}`,
    " * Theme-independent tokens live on :root so they exist even with the Leo skin switched off;",
    " * colors and shadows follow the active Zai theme class on <html>, falling back to the system",
    " * color scheme on pages without the app shell (e.g. the ⌥Space quick panel). */",
    ":root {",
    ...root,
    "}",
    "",
    ":root {",
    ...themed("light"),
    "}",
    "",
    "@media (prefers-color-scheme: dark) {",
    "  :root {",
    ...themed("dark").map((line) => `  ${line}`),
    "  }",
    "}",
    "",
    "html.theme-zai-dark {",
    ...themed("dark"),
    "}",
    "",
    "html.theme-zai-light {",
    ...themed("light"),
    "}",
    "",
  ].join("\n");
}

function ts() {
  const { motion } = tokens;
  // motion/react spring: bounce ≈ 1 − dampingFraction (施工详案 §3.2), visualDuration = response.
  const bounce = Math.round((1 - motion.spring.damping) * 100) / 100;
  return [
    `// ${HEADER}`,
    "",
    "/** Durations in seconds (motion/react) — same steps as the --leo-dur-* CSS tokens. */",
    "export const LEO_DURATION = {",
    ...Object.entries(motion.duration).map(([step, ms]) => `  d${step}: ${ms / 1000},`),
    "} as const;",
    "",
    `export const LEO_BEAT_SECONDS = ${motion.beat / 1000};`,
    `export const LEO_EASE_OUT = [${motion.ease.out.join(", ")}] as const;`,
    `export const LEO_EASE_SETTLE = [${motion.ease.settle.join(", ")}] as const;`,
    "",
    "/** iOS spring(response, dampingFraction) expressed for motion/react. */",
    "export const LEO_SPRING = {",
    '  type: "spring",',
    `  visualDuration: ${motion.spring.response},`,
    `  bounce: ${bounce},`,
    "} as const;",
    "",
    `export const LEO_PRESS = { scale: ${motion.press.scale}, duration: ${motion.press.duration / 1000} } as const;`,
    "",
  ].join("\n");
}

function swiftColor(hexOrRgba) {
  const hex = /^#([0-9a-f]{6})$/i.exec(hexOrRgba);
  if (hex) {
    const n = Number.parseInt(hex[1], 16);
    return `RGBA(r: ${(n >> 16) & 255}, g: ${(n >> 8) & 255}, b: ${n & 255}, a: 1)`;
  }
  const rgba = /^rgba\((\d+),\s*(\d+),\s*(\d+),\s*([\d.]+)\)$/i.exec(hexOrRgba);
  if (rgba) return `RGBA(r: ${rgba[1]}, g: ${rgba[2]}, b: ${rgba[3]}, a: ${Number(rgba[4])})`;
  throw new Error(`unsupported color literal: ${hexOrRgba}`);
}

function swift() {
  const { color, motion, radius, space, font } = tokens;
  const lines = [
    `// ${HEADER}`,
    "// Not wired yet: the iOS line maps LeoTheme / LeoMotion onto these constants.",
    "",
    "enum LeoTokens {",
    "    struct RGBA: Sendable {",
    "        let r: Double",
    "        let g: Double",
    "        let b: Double",
    "        let a: Double",
    "    }",
    "",
    "    struct ThemedColor: Sendable {",
    "        let dark: RGBA",
    "        let light: RGBA",
    "    }",
    "",
    "    enum Color {",
    ...Object.entries(color).map(
      ([key, value]) =>
        `        static let ${key} = ThemedColor(dark: ${swiftColor(value.dark)}, light: ${swiftColor(value.light)})`,
    ),
    "    }",
    "",
    "    enum Spacing {",
    ...Object.entries(space).map(([step, px]) => `        static let s${step}: Double = ${px}`),
    "    }",
    "",
    "    enum Radius {",
    ...["field", "surface", "bubble", "composer", "pill"].map(
      (key) => `        static let ${key}: Double = ${radius[key]}`,
    ),
    "    }",
    "",
    "    enum Motion {",
    ...Object.entries(motion.duration).map(
      ([step, ms]) => `        static let duration${step}: Double = ${ms / 1000}`,
    ),
    `        static let beat: Double = ${motion.beat / 1000}`,
    `        static let springResponse: Double = ${motion.spring.response}`,
    `        static let springDamping: Double = ${motion.spring.damping}`,
    `        static let easeOut: [Double] = [${motion.ease.out.join(", ")}]`,
    `        static let easeSettle: [Double] = [${motion.ease.settle.join(", ")}]`,
    "    }",
    "",
    "    /// Dynamic Type style names matching the Mac text-ui-* roles.",
    "    enum TypeRole {",
    ...Object.entries(font.ui).map(([key, value]) => `        static let ${key} = "${value.ios}"`),
    "    }",
    "",
    `    static let touchTarget: Double = ${tokens.touchTarget}`,
    `    static let readingMaxWidth: Double = ${tokens.readingMaxWidth}`,
    "}",
    "",
  ];
  return lines.join("\n");
}

const outputs = [
  ["src/mac/leophone/packages/ui/src/leo/skin/leo-tokens.css", css()],
  ["src/mac/leophone/packages/ui/src/leo/skin/leoTokens.generated.ts", ts()],
  ["src/ios/Shared/LeoTokens.generated.swift", swift()],
];

const check = process.argv.includes("--check");
const stale = [];
for (const [path, content] of outputs) {
  const absolute = join(repoRoot, path);
  if (check) {
    if (!existsSync(absolute) || readFileSync(absolute, "utf8") !== content) stale.push(path);
  } else {
    writeFileSync(absolute, content);
    console.log(`[gen-tokens] wrote ${relative(process.cwd(), absolute)}`);
  }
}
if (check) {
  if (stale.length > 0) {
    console.error(`[gen-tokens] stale or missing (run node design/gen-tokens.mjs):\n- ${stale.join("\n- ")}`);
    process.exit(1);
  }
  console.log(`[gen-tokens] ✓ ${outputs.length} generated files match design/tokens.json`);
}
